def paint(n: int, ops: list[list[int]]) -> list[list[int]]:
    if not any(op[0] == 1 for op in ops):
        return []

    coordinates = sorted({x for op in ops for x in (op[1], op[2] + 1)})
    index = {x: i for i, x in enumerate(coordinates)}
    k = len(coordinates) - 1
    widths = [coordinates[i + 1] - coordinates[i] for i in range(k)]

    size = 1
    while size < k:
        size <<= 1

    infinity = len(ops)
    minimum = [infinity] * (2 * size)
    minimum[size:size + k] = [-1] * k

    # Find the last erase affecting each compressed interval.
    parent = list(range(k + 1))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    for timestamp in range(len(ops) - 1, -1, -1):
        op = ops[timestamp]
        if op[0] == 0:
            right = index[op[2] + 1]
            i = find(index[op[1]])
            while i < right:
                minimum[size + i] = timestamp
                parent[i] = find(i + 1)
                i = parent[i]

    for node in range(size - 1, 0, -1):
        minimum[node] = min(minimum[node * 2], minimum[node * 2 + 1])

    paints = [
        (op[3], timestamp, index[op[1]], index[op[2] + 1])
        for timestamp, op in enumerate(ops)
        if op[0] == 1
    ]
    paints.sort(reverse=True)

    del parent, index, coordinates

    # Claim unclaimed intervals whose last erase precedes this paint.
    def claim(node, left, right, query_left, query_right, timestamp):
        if minimum[node] >= timestamp:
            return 0

        if right - left == 1:
            minimum[node] = infinity
            return widths[left]

        middle = (left + right) // 2
        child = node * 2
        count = 0

        if query_left < middle:
            count += claim(
                child, left, middle, query_left, query_right, timestamp
            )
        if query_right > middle:
            count += claim(
                child + 1, middle, right, query_left, query_right, timestamp
            )

        minimum[node] = min(minimum[child], minimum[child + 1])
        return count

    result = []
    for colour, timestamp, left, right in paints:
        count = claim(1, 0, size, left, right, timestamp)
        if count:
            if result and result[-1][0] == colour:
                result[-1][1] += count
            else:
                result.append([colour, count])

    result.reverse()
    return result
